```typescript
/**
 * pAVF Compass Clinical Logic Engine
 * Based on: SIR Practice Guidance Document on Percutaneous Arteriovenous Fistulae
 * for Dialysis Access — Dolmatch et al., JVIR 2025 (Vol 36, Issue 12, pp 1945-1957)
 */

// ─── Patient Data Types ────────────────────────────────────────────────────────

export interface PAVFPatientData {
  // Demographics
  patientName: string;
  patientAge: number;
  patientId?: string;

  // Vascular Access History
  priorCentralVenousDevices: boolean; // pacemakers, catheters → risk of central vein obstruction
  priorAVAccessSurgeries: boolean;
  superficialChestCollaterals: boolean; // suggests chronic thoracic venous obstruction

  // Arterial Assessment
  arterialCalcification: "none" | "mild" | "moderate" | "severe";
  barbeauTest: "A" | "B" | "C" | "D"; // A=no damping, B=damping, C=loss+recovery<120s, D=loss no recovery
  radialPulsePresent: boolean;
  ulnarPulsePresent: boolean;
  brachialPulsePresent: boolean;
  arterialDopplerNormal: boolean; // normal waveforms and velocities

  // Venous Assessment (Vessel Mapping)
  perforatorVeinDiameter: number; // mm — ≥2 mm recommended
  perforatorVeinPatent: boolean;
  superficialVeinDepth: number; // mm from skin — ≤6 mm required for cannulation
  superficialVeinPatent: boolean;
  deepVeinDiameter: number; // mm — approximately 2 mm needed
  centralVeinsPatent: boolean; // thoracic central veins

  // Surgical AVF Feasibility
  surgicalAVFFeasible: boolean; // Brescia-Cimino or snuff-box at wrist possible
  surgicalAvailability: boolean; // local surgical expertise available
  patientPrefersPAVF: boolean;

  // Urgency / Timeline
  urgentDialysisNeeded: boolean; // rapidly approaching dialysis need

  // Comorbidities
  armThickness: "thin" | "normal" | "obese";
  activeInfection: boolean; // contraindication for nerve block
  anticoagulated: boolean; // anticoagulation given after nerve block

  // Maturation Follow-up (post-procedure)
  isPostProcedure?: boolean;
  weeksPostProcedure?: number;
  brachialArteryFlowMlMin?: number; // mL/min
  cannulationVeinDiameterMm?: number; // Rule of 6: ≥6 mm
  cannulationVeinDepthMm?: number; // Rule of 6: ≤6 mm from skin
  fistulaPalpableWithTourniquet?: boolean;
  deepVeinDiversionPresent?: boolean; // preferential flow to deep brachial veins
  superficialVeinDiversionPresent?: boolean; // flow away from intended cannulation vein
  cannulationVeinTooDeep?: boolean;
  intraoperativeBlush?: boolean; // contrast blush — usually resolves
}

// ─── Result Types ──────────────────────────────────────────────────────────────

export type PAVFEligibility =
  | "ELIGIBLE"
  | "ELIGIBLE_PREFERRED" // pAVF preferred over surgical
  | "CONSIDER_SURGICAL_FIRST" // surgical AVF should be considered first
  | "INELIGIBLE"
  | "NEEDS_FURTHER_WORKUP";

export type PAVFMaturationStatus =
  | "MATURE_READY_FOR_CANNULATION"
  | "IMMATURE_INFLOW_STENOSIS"
  | "IMMATURE_DEEP_VEIN_DIVERSION"
  | "IMMATURE_SUPERFICIAL_DIVERSION"
  | "IMMATURE_VEIN_TOO_DEEP"
  | "TOO_EARLY_TO_ASSESS" // <4 weeks
  | "EARLY_FOLLOW_UP_NEEDED"; // 1-2 weeks post-procedure

export interface PAVFContraindication {
  id: string;
  label: string;
  severity: "absolute" | "relative";
  guidance: string;
}

export interface PAVFRecommendation {
  category: string;
  recommendation: string;
  guidanceStatementRef?: string; // e.g. "GS-1", "GS-9"
  evidenceLevel?: string;
}

export interface PAVFResult {
  eligibility: PAVFEligibility;
  eligibilityLabel: string;
  eligibilityColor: "green" | "yellow" | "orange" | "red";

  contraindications: PAVFContraindication[];
  warnings: string[];
  recommendations: PAVFRecommendation[];

  // Vessel mapping summary
  vesselMappingAdequate: boolean;
  vesselMappingIssues: string[];

  // Device suggestion
  deviceSuggestion: "WavelinQ" | "Ellipsys (historical)" | "Either" | "None";
  deviceRationale: string;

  // Maturation status (post-procedure)
  maturationStatus?: PAVFMaturationStatus;
  maturationLabel?: string;
  maturationInterventions?: string[];

  // CPT coding guidance
  cptCode: "36836" | "36837" | "N/A";
  cptDescription: string;

  // Follow-up schedule
  followUpSchedule: string[];

  // Summary
  clinicalSummary: string;
  timestamp: Date;
}

// ─── Core Classification Function ─────────────────────────────────────────────

export function assessPAVF(data: PAVFPatientData): PAVFResult {
  const contraindications: PAVFContraindication[] = [];
  const warnings: string[] = [];
  const recommendations: PAVFRecommendation[] = [];
  const vesselMappingIssues: string[] = [];
  const maturationInterventions: string[] = [];

  // ── 1. Absolute Contraindications ──────────────────────────────────────────

  // Barbeau D: loss of pulse without recovery — inadequate palmar arch collateral
  if (data.barbeauTest === "D") {
    contraindications.push({
      id: "barbeau_d",
      label: "Barbeau Test Type D — Inadequate palmar arch collateral circulation",
      severity: "absolute",
      guidance:
        "Loss of pulse tracing without recovery within 120 seconds indicates inadequate ulnopalmar collateral flow. pAVF creation risks hand ischemia. Surgical AVF at wrist is also contraindicated. Consider upper arm access or AV graft. (GS-1)",
    });
  }

  // Active infection at nerve block site
  if (data.activeInfection) {
    contraindications.push({
      id: "active_infection",
      label: "Active infection — Contraindication to brachial plexus block",
      severity: "absolute",
      guidance:
        "Nerve blocks are contraindicated when the needle path passes through inflamed or infected tissue. Delay procedure until infection resolves. (GS-6)",
    });
  }

  // Central vein obstruction with superficial chest collaterals
  if (data.superficialChestCollaterals && !data.centralVeinsPatent) {
    contraindications.push({
      id: "central_vein_obstruction",
      label: "Suspected thoracic central venous obstruction",
      severity: "absolute",
      guidance:
        "Superficial chest collateral veins indicate chronic thoracic venous obstruction. Venography is required to determine the degree of obstruction before pAVF creation. Treat obstruction prior to proceeding. (GS-1)",
    });
  }

  // Severe arterial calcification
  if (data.arterialCalcification === "severe") {
    contraindications.push({
      id: "severe_calcification",
      label: "Severe arterial calcification",
      severity: "absolute",
      guidance:
        "Severe mural calcification prevents radiofrequency fistula creation with the WavelinQ device. Consider surgical AVF or AV graft. (GS-9)",
    });
  }

  // ── 2. Vessel Mapping Assessment ───────────────────────────────────────────

  if (!data.perforatorVeinPatent) {
    vesselMappingIssues.push("No patent perforator vein identified — pAVF creation not possible without a connecting perforator vein");
    contraindications.push({
      id: "no_perforator",
      label: "No patent perforator vein",
      severity: "absolute",
      guidance:
        "A patent perforator vein connecting the deep to superficial venous systems is essential for pAVF creation. Without it, pAVF cannot be performed. (GS-2)",
    });
  } else if (data.perforatorVeinDiameter < 2) {
    vesselMappingIssues.push(
      `Perforator vein diameter ${data.perforatorVeinDiameter} mm — below the recommended ≥2 mm threshold`
    );
    warnings.push(
      "Perforator vein <2 mm: pAVF creation is possible but not recommended as standard practice. Proceed with caution. (GS-2, refs 7,8)"
    );
  }

  if (!data.superficialVeinPatent) {
    vesselMappingIssues.push("No patent superficial outflow vein — cannulation not possible");
    contraindications.push({
      id: "no_superficial_vein",
      label: "No patent superficial outflow vein",
      severity: "absolute",
      guidance:
        "Patent superficial upper arm outflow veins are required for 2-needle cannulation. Without them, hemodialysis cannot be performed via pAVF. (GS-2)",
    });
  } else if (data.superficialVeinDepth > 6) {
    vesselMappingIssues.push(
      `Superficial vein depth ${data.superficialVeinDepth} mm — exceeds the ≤6 mm cannulation threshold`
    );
    warnings.push(
      "Superficial vein >6 mm from skin: Cannulation will be difficult. Surgical elevation or liposuction may be needed post-maturation. (GS-2, ref 7)"
    );
  }

  if (!data.arterialDopplerNormal) {
    vesselMappingIssues.push("Abnormal arterial Doppler waveforms or velocities");
    warnings.push("Abnormal arterial Doppler findings: Evaluate for inflow disease before proceeding. (GS-2)");
  }

  if (data.arterialCalcification === "moderate") {
    vesselMappingIssues.push("Moderate arterial calcification noted");
    warnings.push(
      "Moderate calcification may impede WavelinQ radiofrequency activation. Have PTA balloon available as rescue (balloon 1 mm larger than artery diameter). (GS-9)"
    );
  }

  if (!data.centralVeinsPatent && !data.superficialChestCollaterals) {
    warnings.push(
      "Central vein patency uncertain. If thoracic central vein obstruction is suspected, venography may be required. (GS-1)"
    );
  }

  if (data.priorCentralVenousDevices) {
    warnings.push(
      "Prior or current thoracic central venous devices (pacemakers/catheters) noted — assess for central venous obstruction before proceeding. (GS-1)"
    );
  }

  if (data.priorAVAccessSurgeries) {
    warnings.push(
      "Prior AV access surgeries: Review anatomy carefully. Prior surgical scarring may alter venous anatomy. (GS-1)"
    );
  }

  // ── 3. Eligibility Determination ───────────────────────────────────────────

  const hasAbsoluteContraindication = contraindications.some((c) => c.severity === "absolute");

  let eligibility: PAVFEligibility;
  let eligibilityLabel: string;
  let eligibilityColor: "green" | "yellow" | "orange" | "red";

  if (hasAbsoluteContraindication) {
    eligibility = "INELIGIBLE";
    eligibilityLabel = "Not a Candidate for pAVF";
    eligibilityColor = "red";
  } else if (vesselMappingIssues.length > 0) {
    eligibility = "NEEDS_FURTHER_WORKUP";
    eligibilityLabel = "Further Workup Required";
    eligibilityColor = "orange";
  } else if (data.surgicalAVFFeasible && data.surgicalAvailability && !data.patientPrefersPAVF && !data.urgentDialysisNeeded) {
    eligibility = "CONSIDER_SURGICAL_FIRST";
    eligibilityLabel = "Consider Surgical AVF First";
    eligibilityColor = "yellow";
  } else if (
    !data.surgicalAVFFeasible ||
    !data.surgicalAvailability ||
    data.patientPrefersPAVF ||
    data.urgentDialysisNeeded
  ) {
    eligibility = "ELIGIBLE_PREFERRED";
    eligibilityLabel = "pAVF Preferred — Proceed";
    eligibilityColor = "green";
  } else {
    eligibility = "ELIGIBLE";
    eligibilityLabel = "Eligible for pAVF";
    eligibilityColor = "green";
  }

  // ── 4. Device Suggestion ───────────────────────────────────────────────────

  let deviceSuggestion: PAVFResult["deviceSuggestion"] = "WavelinQ";
  let deviceRationale =
    "WavelinQ 4F dual-catheter system (BD) is the currently available device. Requires US + fluoroscopic guidance. Physician must complete 2-hour didactic webinar, 1-on-1 training, and 3 simulated proctored cases before first procedure. (GS-7, GS-9)";

  if (data.arterialCalcification === "severe") {
    deviceSuggestion = "None";
    deviceRationale = "Severe calcification prevents radiofrequency activation. Neither device is suitable.";
  } else if (data.arterialCalcification === "moderate") {
    deviceRationale +=
      " Note: moderate calcification may impede activation — have rescue PTA balloon (1 mm > artery diameter) available.";
  }

  // ── 5. CPT Code ────────────────────────────────────────────────────────────

  // 36836 = single access (Ellipsys-style), 36837 = dual access (WavelinQ-style)
  const cptCode: PAVFResult["cptCode"] =
    eligibility === "INELIGIBLE" ? "N/A" : deviceSuggestion === "WavelinQ" ? "36837" : "36836";

  const cptDescription =
    cptCode === "36837"
      ? "CPT 36837 — Percutaneous AVF creation, upper extremity, separate access sites (artery + vein). Includes maturation procedures, imaging guidance, and radiologic supervision. RVU: 9.30"
      : cptCode === "36836"
      ? "CPT 36836 — Percutaneous AVF creation, upper extremity, single access. Includes maturation procedures, imaging guidance, and radiologic supervision. RVU: 7.20"
      : "No CPT code applicable — patient not a candidate.";

  // ── 6. Recommendations ────────────────────────────────────────────────────

  if (eligibility !== "INELIGIBLE") {
    recommendations.push({
      category: "Pre-Procedure",
      recommendation:
        "Perform comprehensive vessel mapping with tourniquet on upper arm, patient relaxed and warm. Assess: arterial calcification, Doppler waveforms, Barbeau test, perforator vein (≥2 mm), superficial vein depth (≤6 mm), central vein patency.",
      guidanceStatementRef: "GS-1, GS-2, GS-3",
    });

    recommendations.push({
      category: "Anesthesia",
      recommendation:
        "Brachial plexus block (supraclavicular or infraclavicular) under US guidance using 2% lidocaine (15–30 mL). Avoid bupivacaine (prolonged block). Give anticoagulation after block. Block takes effect in 10–15 minutes.",
      guidanceStatementRef: "GS-5, GS-6",
    });

    recommendations.push({
      category: "Patient Counseling",
      recommendation:
        "Inform patient: technical success >95%, but ~80% achieve successful cannulation. Additional maturation procedures are common, especially in year 1. Dialysis center staff training is often required. Risks: bleeding, infection, nerve irritation, swelling, steal syndrome, surgical revision.",
      guidanceStatementRef: "GS-4",
    });

    recommendations.push({
      category: "Procedure",
      recommendation:
        "WavelinQ: Apply tourniquet for venous dilation. Administer vasodilator cocktail (verapamil + heparin + nitroglycerin) via arterial sheath. Achieve parallel catheter alignment (magnets) just distal to perforator connection. Activate RF pulse (0.7 s; may increase to 1.0 s if needed). Confirm fistula with contrast injection. If blush seen, wait — fistula usually becomes apparent within minutes.",
      guidanceStatementRef: "GS-9",
    });

    if (data.deepVeinDiameter > 0) {
      recommendations.push({
        category: "Intraoperative",
        recommendation:
          "Assess for preferential deep brachial vein flow after creation. If deep vein diversion reduces superficial cannulation flow, perform coil embolization of one brachial vein (4/5F catheter via US-guided retrograde brachial vein access or radial artery access). Can be performed at time of creation or later visit.",
        guidanceStatementRef: "GS-9",
      });
    }

    recommendations.push({
      category: "Follow-Up",
      recommendation:
        "Schedule office visit + US study at 1–2 weeks post-procedure. Assess: brachial artery flow (mL/min), cannulation vein diameter, cannulation vein depth, perforator vein patency. Address maturation issues early. Goal: 2-needle cannulation allowing hemodialysis as prescribed.",
      guidanceStatementRef: "GS-11",
    });

    recommendations.push({
      category: "Maturation Target (Rule of 6s)",
      recommendation:
        "Cannulation vein: diameter ≥6 mm, depth ≤6 mm from skin, flow ≥600 mL/min. For pAVFs specifically: fistula should be palpable with tourniquet downstream at time of cannulation attempt. pAVFs feel softer than surgical fistulae — train dialysis staff accordingly.",
      guidanceStatementRef: "GS-15, GS-16",
    });

    if (data.urgentDialysisNeeded) {
      recommendations.push({
        category: "Urgency",
        recommendation:
          "Urgent dialysis need: A well-functioning pAVF program can map and create the pAVF within 1 week. Successful cannulation of a mature pAVF is expected approximately 4 weeks after creation. Coordinate with nephrology for bridging access if needed.",
        guidanceStatementRef: "GS-4",
      });
    }
  }

  if (eligibility === "CONSIDER_SURGICAL_FIRST") {
    recommendations.push({
      category: "Surgical Referral",
      recommendation:
        "Surgical Brescia-Cimino AVF or snuff-box AVF at the wrist should be considered first when feasible and surgical expertise is available. pAVF is preferred when forearm veins are unsuitable for surgical AVF, surgical access is unavailable, or patient preference favors percutaneous approach.",
      guidanceStatementRef: "GS-1",
    });
  }

  // ── 7. Maturation Assessment (Post-Procedure) ─────────────────────────────

  let maturationStatus: PAVFMaturationStatus | undefined;
  let maturationLabel: string | undefined;

  if (data.isPostProcedure && data.weeksPostProcedure !== undefined) {
    if (data.weeksPostProcedure < 1) {
      maturationStatus = "EARLY_FOLLOW_UP_NEEDED";
      maturationLabel = "Schedule 1–2 Week Follow-Up Visit + US Study";
    } else if (data.weeksPostProcedure < 4) {
      maturationStatus = "TOO_EARLY_TO_ASSESS";
      maturationLabel = "Too Early for Cannulation Assessment — Continue Monitoring";
    } else {
      // Assess maturation
      const ruleOf6Met =
        (data.cannulationVeinDiameterMm ?? 0) >= 6 &&
        (data.cannulationVeinDepthMm ?? 99) <= 6 &&
        (data.fistulaPalpableWithTourniquet ?? false);

      if (ruleOf6Met) {
        maturationStatus = "MATURE_READY_FOR_CANNULATION";
        maturationLabel = "Mature — Ready for Cannulation";
      } else if (data.deepVeinDiversionPresent) {
        maturationStatus = "IMMATURE_DEEP_VEIN_DIVERSION";
        maturationLabel = "Immature — Deep Vein Diversion";
        maturationInterventions.push(
          "Coil embolization of one brachial vein (4/5F catheter via US-guided retrograde brachial vein or radial artery access). Avoid excessive embolization to prevent venous hypertension. (GS-13)"
        );
      } else if (data.superficialVeinDiversionPresent) {
        maturationStatus = "IMMATURE_SUPERFICIAL_DIVERSION";
        maturationLabel = "Immature — Superficial Vein Diversion";
        maturationInterventions.push(
          "Banding or ligation of median basilic or median cubital vein to redirect flow to cephalic cannulation vein. Avoid banding basilic vein 2–3 cm from antecubital fossa (risk of medial antebrachial cutaneous nerve injury). (GS-13)"
        );
      } else if (data.cannulationVeinTooDeep) {
        maturationStatus = "IMMATURE_VEIN_TOO_DEEP";
        maturationLabel = "Immature — Cannulation Vein Too Deep";
        maturationInterventions.push(
          "Surgical vein elevation (especially basilic vein) or liposuction to reduce subcutaneous adipose tissue between cannulation vein and skin. (GS-13)"
        );
      } else {
        // Default: likely inflow stenosis
        maturationStatus = "IMMATURE_INFLOW_STENOSIS";
        maturationLabel = "Immature — Evaluate for Inflow/Perforator Stenosis";
        maturationInterventions.push(
          "Balloon angioplasty of anastomosis and/or perforator vein stenosis. Consider peripheral cutting balloon for resistant stenoses. Use arterial access for diagnosis and intervention. (GS-13, GS-14)"
        );
      }
    }
  }

  // ── 8. Follow-Up Schedule ─────────────────────────────────────────────────

  const followUpSchedule: string[] = [
    "1–2 weeks post-procedure: Office visit + US study. Assess brachial artery flow, cannulation vein diameter/depth, perforator vein patency. Address early maturation issues.",
    "4 weeks post-procedure: Assess cannulation readiness (Rule of 6s: vein ≥6 mm diameter, ≤6 mm depth, palpable with tourniquet).",
    "Ongoing: Dialysis center staff training on pAVF cannulation technique. IR physician is primary contact for cannulation troubleshooting.",
    "If cannulation fails: IR physician should visit dialysis unit to assess and assist with successful cannulation.",
    "Subsequent interventions: Use CPT codes 36901–36909 for pAVF maintenance procedures after initial creation date.",
  ];

  // ── 9. Vessel Mapping Summary ─────────────────────────────────────────────

  const vesselMappingAdequate =
    data.perforatorVeinPatent &&
    data.perforatorVeinDiameter >= 2 &&
    data.superficialVeinPatent &&
    data.superficialVeinDepth <= 6 &&
    data.centralVeinsPatent &&
    data.arterialDopplerNormal &&
    data.arterialCalcification !== "severe";

  // ── 10. Clinical Summary ──────────────────────────────────────────────────

  let clinicalSummary = "";
  if (eligibility === "INELIGIBLE") {
    clinicalSummary = `Patient is NOT a candidate for pAVF creation due to: ${contraindications.map((c) => c.label).join("; ")}. ${
      data.barbeauTest === "D" ? "Consider upper arm AV graft." : "Alternative access strategy required."
    }`;
  } else if (eligibility === "NEEDS_FURTHER_WORKUP") {
    clinicalSummary = `Patient requires further workup before pAVF candidacy can be confirmed: ${vesselMappingIssues.join("; ")}. Repeat vessel mapping after addressing these issues.`;
  } else if (eligibility === "CONSIDER_SURGICAL_FIRST") {
    clinicalSummary =
      "Patient has suitable anatomy for pAVF but surgical AVF (Brescia-Cimino or snuff-box) should be considered first given surgical feasibility and availability. If surgical AVF fails or is declined, pAVF is an appropriate next step.";
  } else if (eligibility === "ELIGIBLE_PREFERRED") {
    const reasons: string[] = [];
    if (!data.surgicalAVFFeasible) reasons.push("forearm veins unsuitable for surgical AVF");
    if (!data.surgicalAvailability) reasons.push("no local surgical expertise");
    if (data.patientPrefersPAVF) reasons.push("patient preference");
    if (data.urgentDialysisNeeded) reasons.push("urgent dialysis need (pAVF achievable within 1 week)");
    clinicalSummary = `Patient is a preferred candidate for pAVF (${reasons.join(", ")}). Vessel mapping is adequate. Proceed with ${deviceSuggestion} system. Technical success expected >95%; cannulation success ~80%. Maturation procedures may be required.`;
  } else {
    clinicalSummary =
      "Patient is eligible for pAVF creation. Vessel mapping is adequate. Proceed with WavelinQ system. Technical success expected >95%; cannulation success ~80%. Maturation procedures may be required in year 1.";
  }

  return {
    eligibility,
    eligibilityLabel,
    eligibilityColor,
    contraindications,
    warnings,
    recommendations,
    vesselMappingAdequate,
    vesselMappingIssues,
    deviceSuggestion,
    deviceRationale,
    maturationStatus,
    maturationLabel,
    maturationInterventions: maturationInterventions.length > 0 ? maturationInterventions : undefined,
    cptCode,
    cptDescription,
    followUpSchedule,
    clinicalSummary,
    timestamp: new Date(),
  };
}

// ─── Barbeau Test Helper ───────────────────────────────────────────────────────

export const BARBEAU_DESCRIPTIONS: Record<string, string> = {
  A: "Type A — No damping of pulse tracing immediately after compression. Patent palmar arch.",
  B: "Type B — Damping of pulse tracing. Adequate collateral flow.",
  C: "Type C — Loss of pulse tracing followed by recovery within 120 seconds. Adequate collateral flow.",
  D: "Type D — Loss of pulse tracing without recovery within 120 seconds. INADEQUATE palmar arch — pAVF/radial access contraindicated.",
};

// ─── Eligibility Color Map ─────────────────────────────────────────────────────

export const ELIGIBILITY_COLORS: Record<PAVFEligibility, string> = {
  ELIGIBLE: "#16a34a",
  ELIGIBLE_PREFERRED: "#15803d",
  CONSIDER_SURGICAL_FIRST: "#ca8a04",
  INELIGIBLE: "#dc2626",
  NEEDS_FURTHER_WORKUP: "#ea580c",
};
