          text-align: left;
          font-weight: 600;
          color: #1e293b;
          border: 1px solid #cbd5e1;
        }
        td {
          padding: 10px;
          border: 1px solid #cbd5e1;
          color: #475569;
        }
        tr:nth-child(even) {
          background: #f8fafc;
        }
        .footer {
          margin-top: 40px;
          padding-top: 20px;
          border-top: 1px solid #e2e8f0;
          font-size: 11px;
          color: #64748b;
          text-align: center;
        }
        .disclaimer {
          background: #fef2f2;
          border: 1px solid #fecaca;
